// Pure helpers for the Chaos Crossing v002 arena world. No Phaser import so
// the geometry, layer visibility, mount assembly and defender-pose logic stay
// unit-testable. All art placement uses the same board-to-screen transform as
// entities: screen = (x*5, seat===0 ? (160-y)*5 : y*5).
//
// The runtime manifest is generated by scripts/import-arena-v002.ts from the
// v002 layer/mount/display-proposal manifests. Half-size exports place the
// 600x920 art at (-50,-60) in the 500x800 board; mount exports display at
// scale 0.5 with pivot (0.5, 0.875). Anchor values are authored in master
// board pixels (10 px/unit) and halve to board pixels.

export const ARENA_URL = "/assets/arena/chaos-crossing/v002";
export const BOARD_W = 500;
export const BOARD_H = 800;
export const MASTER_ORIGIN_X = 100;
export const MASTER_ORIGIN_Y = 120;
export const MASTER_PX_PER_UNIT = 10;
export const PX_PER_UNIT = 5;

export type LayerState =
  | "static"
  | "ripple-a"
  | "ripple-b"
  | "rift-open"
  | "rift-closed"
  | "chaos-warning"
  | "chaos-active"
  | "chaos-expiry";

export interface ArenaLayer {
  id: string;
  path: string;
  zOrder: number;
  defaultVisible: boolean;
  state: LayerState;
  stateRule: string;
}

export interface MountPose {
  path: string;
  weaponAnchorLocalBoardPixels: [number, number];
  firingAllowed: boolean;
}

export interface MountRole {
  pivotNormalized: [number, number];
  displayScale: number;
  seatLocalBoardPixels: [number, number];
  healthBarLocalBoardRectangle: [number, number, number, number];
  renderOrder: string[];
  parts: Record<"structure-base" | "socket-platform" | "front-rim", string | undefined>;
  poses: Record<string, MountPose>;
}

export interface MountPlacement {
  id: string;
  mountRole: string;
  groundAnchorPixels: [number, number];
  directionRequested: string;
}

export interface ArenaManifest {
  arenaId: string;
  schemaVersion: number;
  board: {
    artCanvas: [number, number];
    boardOffset: [number, number];
    boardSize: [number, number];
    pxPerUnit: number;
    masterOrigin: [number, number];
    masterPxPerUnit: number;
  };
  layers: ArenaLayer[];
  mounts: Record<string, MountRole>;
  placements: MountPlacement[];
}

export type Seat = 0 | 1;

// Same point transform the renderer uses for entities. Seat 1 is a vertical
// mirror only (x is unchanged), so environment art flips vertically, never
// rotates 180 degrees.
export const boardPoint = (x: number, y: number, seat: Seat): [number, number] => [
  x * PX_PER_UNIT,
  (seat === 0 ? 160 - y : y) * PX_PER_UNIT,
];

// Master board pixels -> arena units (inverts px = 100 + 10x, py = 120 + 10*(160 - y)).
export const masterToArena = (mx: number, my: number): [number, number] => [
  (mx - MASTER_ORIGIN_X) / MASTER_PX_PER_UNIT,
  160 - (my - MASTER_ORIGIN_Y) / MASTER_PX_PER_UNIT,
];

// Master board pixels -> screen board pixels through the seat transform.
export const masterToScreen = (mx: number, my: number, seat: Seat): [number, number] => {
  const [x, y] = masterToArena(mx, my);
  return boardPoint(x, y, seat);
};

// A mount local anchor (authored in master board pixels relative to the root)
// applied to a structure's screen position. Defenders stay upright for both
// seats, so the same unflipped local offset is used for seat 0 and seat 1.
export const anchorScreenOffset = (local: [number, number]): [number, number] => [local[0] / 2, local[1] / 2];

// Weapon origin in arena coordinates: structure ground anchor (master px)
// plus the pose's local weapon anchor (master px), inverted to arena units.
export const weaponArena = (groundAnchor: [number, number], anchorLocal: [number, number]): [number, number] =>
  masterToArena(groundAnchor[0] + anchorLocal[0], groundAnchor[1] + anchorLocal[1]);

export type StructureKind = "tower" | "core";

export const mountRoleFor = (kind: StructureKind): string => (kind === "core" ? "core-keeper" : "sentinel");

export const placementFor = (m: ArenaManifest, kind: StructureKind, x: number, y: number): MountPlacement | null => {
  const [ax, ay] = boardPoint(x, y, 0);
  // Ground anchors are seat-agnostic master coordinates; match by arena point.
  for (const p of m.placements) {
    const [mx, my] = masterToScreen(p.groundAnchorPixels[0], p.groundAnchorPixels[1], 0);
    if (Math.abs(mx - ax) < 2 && Math.abs(my - ay) < 2 && p.mountRole === mountRoleFor(kind)) return p;
  }
  return null;
};

export interface LayerView {
  riftOpen: boolean;
  anyWarning: boolean;
  anyActive: boolean;
  expiryUntil: number;
  now: number;
  rippleAlt: boolean;
}

// State-driven layer visibility. The ford is controlled only by
// frame.riftOpen; warning/expiry overlays never open it.
export const layerVisible = (l: ArenaLayer, v: LayerView): boolean => {
  switch (l.state) {
    case "ripple-a":
      return !v.rippleAlt;
    case "ripple-b":
      return v.rippleAlt;
    case "rift-open":
      return v.riftOpen;
    case "rift-closed":
      return !v.riftOpen;
    case "chaos-warning":
      return v.anyWarning;
    case "chaos-active":
      return v.anyActive;
    case "chaos-expiry":
      return v.now < v.expiryUntil;
    default:
      return l.defaultVisible;
  }
};

// Ordered mount assembly: base, socket, defender pose, front rim. Destroyed
// structures show only a dimmed base (no defender, socket or rim operator).
export const assemblyFor = (m: ArenaManifest, role: string, pose: string | null): string[] => {
  const r = m.mounts[role];
  if (!r) return [];
  const parts = [`${role}:structure-base`];
  if (pose !== null) {
    if (r.parts["socket-platform"]) parts.push(`${role}:socket-platform`);
    if (r.poses[pose]) parts.push(`${role}:defender-${pose}`);
    if (r.parts["front-rim"]) parts.push(`${role}:front-rim`);
  }
  return parts;
};

// Screen hemisphere decides the directional aim pose. Bottom-half structures
// aim north (up-screen), top-half aim south. Art is never vertically flipped.
export const directionalAim = (screenY: number): "aim-north" | "aim-south" =>
  screenY > BOARD_H / 2 ? "aim-north" : "aim-south";

export interface DefenderState {
  lastHp: number;
  fireUntil: number;
  hitUntil: number;
}

export const newDefenderState = (): DefenderState => ({ lastHp: -1, fireUntil: 0, hitUntil: 0 });

export const FIRE_MS = 150;
export const HIT_MS = 200;

// Advance the visual pose state from authoritative signals only: an hp drop
// shows hit for HIT_MS, a newly attributed projectile shows fire for FIRE_MS.
export const updateDefender = (
  s: DefenderState,
  signal: { hp: number; fired: boolean },
  now: number
): DefenderState => {
  const out = { ...s };
  if (out.lastHp >= 0 && signal.hp < out.lastHp) out.hitUntil = now + HIT_MS;
  if (signal.fired) out.fireUntil = now + FIRE_MS;
  out.lastHp = signal.hp;
  return out;
};

export const defenderPose = (
  s: DefenderState,
  aiming: boolean,
  screenY: number,
  now: number
): string => {
  if (now < s.hitUntil) return "hit";
  if (now < s.fireUntil) return "fire";
  if (aiming) return directionalAim(screenY);
  return "idle";
};

// Deterministic projectile attribution: a projectile whose first-seen arena
// position is within `maxDist` units of a same-owner structure's weapon
// origin is credited to that structure. Returns the structure id or null.
export interface WeaponCandidate {
  id: string;
  owner: number;
  weaponX: number;
  weaponY: number;
}

export const attributeProjectile = (
  proj: { x: number; y: number; owner: number },
  candidates: WeaponCandidate[],
  maxDist = 1.5
): string | null => {
  let best: string | null = null;
  let bestD = maxDist;
  for (const c of candidates) {
    if (c.owner !== proj.owner) continue;
    const d = Math.hypot(proj.x - c.weaponX, proj.y - c.weaponY);
    if (d <= bestD) {
      bestD = d;
      best = c.id;
    }
  }
  return best;
};
